//! Configuration parsing and data structures for postmaster.
//!
//! The config is generated by the Nix module as JSON. It contains only
//! public information (store paths for ciphertext + key *names*).

use std::collections::HashMap;
use std::path::PathBuf;

use serde::Deserialize;

/// Full configuration loaded from the JSON file produced by the Nix module.
/// Unknown fields are rejected (audit 2026-08-02 A21) — same strictness
/// as the exec config.
#[derive(Deserialize, Debug)]
#[serde(deny_unknown_fields)]
pub struct Config {
    /// Where the .env.keys material comes from.
    pub keys: KeysSource,
    /// Absolute socket path → what to serve on it.
    pub credentials: HashMap<PathBuf, Entry>,
}

#[derive(Deserialize, Debug)]
#[serde(rename_all = "snake_case")]
/// Where postmaster should obtain its own private keys.
pub enum KeysSource {
    /// Name under $CREDENTIALS_DIRECTORY (the daemon's own LoadCredential).
    Credential(String),
    /// Absolute filesystem path (must not live in the Nix store).
    File(PathBuf),
}

#[derive(Deserialize, Clone, Debug)]
/// A single credential mapping served by postmaster.
pub struct Entry {
    /// encrypted env file (a Nix store path; ciphertext is public).
    pub env_file: PathBuf,
    /// Which key inside it to serve.
    pub key: String,
    /// Additionally allow this (non-root) user to fetch the credential.
    /// Used by the darwin module, where consumers are launchd daemons
    /// connecting as their own service user rather than pid 1.
    #[serde(default)]
    pub peer_user: Option<String>,
}

/// Parsed command-line arguments for the `serve` invocation.
#[derive(Debug)]
pub struct Args {
    /// Path to the daemon config JSON file.
    pub config: PathBuf,
    /// Bind listener sockets even when not socket-activated.
    pub bind: bool,
    /// Allow non-root peers to connect (dangerous, darwin only).
    pub allow_nonroot: bool,
}

/// The parsed top-level invocation selected from CLI arguments.
#[derive(Debug)]
pub enum Invocation {
    /// `postmaster --config <file.json> [--bind] [--allow-nonroot]`:
    /// run the credential daemon (socket-activated on Linux, bind on macOS).
    Serve(Args),
    /// `postmaster fetch <socket-path>`: connect to a running daemon
    /// socket and write the decrypted bytes to stdout.
    Fetch(PathBuf),
    /// `postmaster exec --config <exec.json> [--check] [--verify-keys]`
    /// `-- <argv…>`: decrypt + inject per the launcher contract, then
    /// execvp argv. See launcher.rs.
    Exec {
        /// Path to the exec config JSON.
        config: PathBuf,
        /// Validate config shape only — no decryption, no exec.
        check: bool,
        /// Preflight: attempt a test decryption of one encrypted value
        /// from each env file before proceeding to exec. Catches stale
        /// keys from a previous rotation cycle that are valid hex but
        /// no longer match the ciphertext (audit finding #4).
        verify_keys: bool,
        /// Child argv — everything after `--` on the command line.
        argv: Vec<String>,
    },
    /// `postmaster setup --config <exec.json> [--recheck] [--unattended]
    /// [--force] [--keys-dir <path>]`: verify platform prerequisites,
    /// create keys directory with correct permissions, optionally seed
    /// keychain items, and validate the environment. Idempotent — skips
    /// steps that are already correct. `--recheck` re-verifies without
    /// creating or modifying anything.
    Setup {
        /// Path to the exec config JSON.
        config: PathBuf,
        /// Verification only — no creation or modification.
        recheck: bool,
        /// Non-interactive mode for automation (fail closed, no prompts).
        unattended: bool,
        /// Re-create or re-seed even if already correct.
        force: bool,
        /// Override the default keys directory path.
        keys_dir: Option<PathBuf>,
    },
    /// `postmaster cleanup --config <exec.json>`: remove all secret files
    /// from the secrets_dir configured in the exec config. Intended for
    /// `ExecStopPost` in systemd or equivalent lifecycle hooks in other
    /// service managers. Does not decrypt — only removes files that
    /// postmaster would have written.
    Cleanup {
        /// Path to the exec config JSON.
        config: PathBuf,
    },
    /// Print help text and exit successfully.
    Help(Option<String>),
    /// Print version and exit successfully.
    Version,
}

/// Crate version, resolved at compile time from `CARGO_PKG_VERSION`.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// Top-level help text shown by `postmaster --help` or `postmaster help`.
pub const HELP_TOP: &str = "postmaster — standalone secret materialization engine\n\n\
USAGE:\n  \
postmaster --config <file.json> [--bind] [--allow-nonroot]\n  \
postmaster fetch <socket-path>\n  \
postmaster exec --config <exec.json> [--check] [--verify-keys] -- <command> [args…]\n  \
postmaster setup --config <exec.json> [--recheck] [--unattended] [--force] [--keys-dir <path>]\n  \
postmaster help [subcommand]\n  \
postmaster --version\n\n\
SUBCOMMANDS:\n  \
exec     Decrypt secrets and exec a child process with them injected\n  \
fetch    Fetch a single secret from a postmaster daemon socket\n  \
setup    Verify environment, create keys directory, seed keychain (idempotent)\n  \
help     Show help for a subcommand or this message\n\n\
OPTIONS:\n  \
--config <path>  Configuration file (required for serve, exec, setup)\n  \
--bind           (serve) Bind listener sockets even if not socket-activated\n  \
--allow-nonroot  (serve) Allow non-root connections (dangerous)\n  \
--check          (exec) Validate config shape only, no decryption or exec\n  \
--verify-keys    (exec) Preflight key freshness check before exec\n  \
--recheck        (setup) Verification only, no creation or modification\n  \
--unattended     (setup) Non-interactive mode for automation (fail closed)\n  \
--force          (setup) Re-create or re-seed even if already correct\n  \
--keys-dir <p>   (setup) Override default keys directory path\n  \
--version, -V    Print version and exit\n  \
--help, -h       Show this help message\n";

/// Help text for the `exec` subcommand.
pub const HELP_EXEC: &str = "postmaster exec — decrypt secrets and exec a child process\n\n\
USAGE:\n  \
postmaster exec --config <exec.json> [--check] [--verify-keys] -- <command> [args…]\n\n\
Decrypts the configured env files and/or bundle files using the loaded key\n\
ring, injects the resolved values into the child environment (or writes them\n\
as files / credential pointers depending on mode), and execs the command.\n\n\
OPTIONS:\n  \
--config <path>  Exec config JSON (required)\n  \
--check          Validate config shape only, no decryption, no exec\n  \
--verify-keys    Preflight: test-decrypt one value per env file before exec\n  \
-- <command>     Everything after `--` is the child argv (required unless --check)\n\n\
The config must specify mode (env/files/credentials), key sources, and\n\
artifact paths. See docs/src/launcher-contract.md for the full contract.\n";

/// Help text for the `fetch` subcommand.
pub const HELP_FETCH: &str = "postmaster fetch — fetch a secret from a daemon socket\n\n\
USAGE:\n  \
postmaster fetch <socket-path>\n\n\
Connects to a running postmaster daemon's AF_UNIX socket, requests the\n\
default secret, and writes the decrypted bytes to stdout. Used internally\n\
by the credentials-mode launcher on macOS (launchd) to pull secrets from\n\
the daemon into the RAM disk.\n\n\
The socket path must be a single relative or absolute path to the AF_UNIX\n\
socket created by `postmaster --config <file.json>`.\n";

/// Help text for the `setup` subcommand.
pub const HELP_SETUP: &str = "postmaster setup — verify environment and create key material\n\n\
USAGE:\n  \
postmaster setup --config <exec.json> [--recheck] [--unattended] [--force] [--keys-dir <path>]\n\n\
Verifies platform prerequisites, creates the keys directory with 0700\n\
permissions, verifies or creates keys files with 0600, optionally seeds\n\
keychain items (macOS, interactive), and validates the environment.\n\n\
Idempotent — each step checks whether the target state is already present\n\
and correct, and skips if it is. Safe to run on every converge cycle.\n\n\
OPTIONS:\n  \
--config <path>   Exec config JSON (required)\n  \
--recheck          Verification only — no creation or modification\n  \
--unattended       Non-interactive mode for automation (fail closed, no prompts)\n  \
--force            Re-create or re-seed even if already correct\n  \
--keys-dir <path>  Override the default keys directory\n\n\
Default keys directory: /var/lib/postmaster (Linux),\n\
~/Library/Application Support/postmaster (macOS).\n";

/// Help text for the `cleanup` subcommand.
pub const HELP_CLEANUP: &str = "postmaster cleanup — remove secret files from secrets_dir\n\n\
USAGE:\n  \
postmaster cleanup --config <exec.json>\n\n\
Reads the exec config, extracts secrets_dir, and removes all regular files\n\
in that directory. Intended for ExecStopPost in systemd or equivalent\n\
lifecycle hooks in other service managers.\n\n\
Does not decrypt — only removes files that postmaster would have written.\n\
Safe to run even if the directory is already empty or does not exist.\n\n\
OPTIONS:\n  \
--config <path>  Exec config JSON (required)\n";

/// Short usage string for error messages.
pub const USAGE: &str = "usage: postmaster --config <file.json> [--bind] [--allow-nonroot]\n       postmaster fetch <socket-path>\n       postmaster exec --config <exec.json> [--check] [--verify-keys]\n       postmaster exec --config <exec.json> [--verify-keys] -- <command> [args…]\n       postmaster setup --config <exec.json> [--recheck] [--unattended] [--force] [--keys-dir <path>]\n       postmaster cleanup --config <exec.json>";

/// Parse command-line arguments from `std::env::args()`.
pub fn parse_args() -> Result<Invocation, String> {
    parse_args_from(std::env::args().skip(1))
}

/// Parse command-line arguments from a provided iterator. Kept simple
/// with no external dependencies (no clap).
pub fn parse_args_from(args: impl IntoIterator<Item = String>) -> Result<Invocation, String> {
    let mut it = args.into_iter().peekable();

    // No args: print help and fail
    if it.peek().is_none() {
        return Err(format!(
            "{HELP_TOP}\n\nerror: no subcommand or --config provided"
        ));
    }

    match it.peek().map(String::as_str) {
        // Global flags that work before any subcommand
        Some("--help") | Some("-h") => {
            it.next();
            if it.next().is_some() {
                return Err("error: --help does not take arguments".into());
            }
            Ok(Invocation::Help(None))
        }
        Some("--version") | Some("-V") => {
            it.next();
            if it.next().is_some() {
                return Err("error: --version does not take arguments".into());
            }
            Ok(Invocation::Version)
        }
        Some("help") => {
            it.next();
            let sub = it.next();
            if it.next().is_some() {
                return Err(
                    "error: `help` takes at most one argument (the subcommand name)".into(),
                );
            }
            Ok(Invocation::Help(sub))
        }
        Some("fetch") => {
            it.next();
            let path = it.next().ok_or("error: fetch requires a socket path")?;
            if it.next().is_some() {
                return Err("error: fetch takes exactly one argument (the socket path)".into());
            }
            Ok(Invocation::Fetch(PathBuf::from(path)))
        }
        Some("exec") => {
            it.next();
            let mut config = None;
            let mut check = false;
            let mut verify_keys = false;
            let mut argv: Vec<String> = Vec::new();
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--check" => check = true,
                    "--verify-keys" => verify_keys = true,
                    "--help" | "-h" => return Ok(Invocation::Help(Some("exec".into()))),
                    "--" => {
                        argv = it.collect();
                        break;
                    }
                    other => {
                        return Err(format!(
                            "error: exec: unknown option `{other}`\n\n{HELP_EXEC}"
                        ));
                    }
                }
            }
            if check {
                if !argv.is_empty() {
                    return Err("error: exec --check does not accept a command after `--`".into());
                }
            } else if argv.is_empty() {
                return Err(format!(
                    "error: exec: missing command after `--`\n\n{HELP_EXEC}"
                ));
            }
            Ok(Invocation::Exec {
                config: config.ok_or("error: exec: missing required --config <exec.json>")?,
                check,
                verify_keys,
                argv,
            })
        }
        Some("setup") => {
            it.next();
            let mut config = None;
            let mut recheck = false;
            let mut unattended = false;
            let mut force = false;
            let mut keys_dir = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--recheck" => recheck = true,
                    "--unattended" | "--non-interactive" => unattended = true,
                    "--force" => force = true,
                    "--keys-dir" => {
                        keys_dir = Some(PathBuf::from(
                            it.next().ok_or("error: --keys-dir requires a path")?,
                        ));
                    }
                    "--help" | "-h" => return Ok(Invocation::Help(Some("setup".into()))),
                    other => {
                        return Err(format!(
                            "error: setup: unknown option `{other}`\n\n{HELP_SETUP}"
                        ));
                    }
                }
            }
            let config = config.ok_or("error: setup: missing required --config <exec.json>")?;
            Ok(Invocation::Setup {
                config,
                recheck,
                unattended,
                force,
                keys_dir,
            })
        }
        Some("cleanup") => {
            it.next();
            let mut config = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--help" | "-h" => return Ok(Invocation::Help(Some("cleanup".into()))),
                    other => {
                        return Err(format!(
                            "error: cleanup: unknown option `{other}`\n\n{HELP_CLEANUP}"
                        ));
                    }
                }
            }
            Ok(Invocation::Cleanup {
                config: config.ok_or("error: cleanup: missing required --config <exec.json>")?,
            })
        }
        // Serve mode (default, no subcommand keyword)
        Some("--config") | Some("--bind") | Some("--allow-nonroot") => {
            let mut config = None;
            let mut bind = false;
            let mut allow_nonroot = false;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--bind" => bind = true,
                    "--allow-nonroot" => allow_nonroot = true,
                    "--help" | "-h" => return Ok(Invocation::Help(None)),
                    other => {
                        return Err(format!("error: unknown option `{other}`\n\n{HELP_TOP}"));
                    }
                }
            }
            Ok(Invocation::Serve(Args {
                config: config.ok_or("error: missing required --config <file.json>")?,
                bind,
                allow_nonroot,
            }))
        }
        Some(other) => Err(format!(
            "error: unknown subcommand `{other}`\n\nTry `postmaster help` for usage.\n"
        )),
        None => unreachable!("empty args handled above"),
    }
}

#[cfg(test)]
#[allow(unused_qualifications, clippy::panic, clippy::unwrap_used)]
/// Tests for CLI argument parsing.
mod tests {
    use super::*;

    fn parse(v: &[&str]) -> Result<Invocation, String> {
        parse_args_from(v.iter().map(ToString::to_string))
    }

    #[test]
    fn parse_exec() {
        match parse(&[
            "exec", "--config", "/e.json", "--", "/bin/app", "--flag", "x",
        ]) {
            Ok(Invocation::Exec {
                config,
                check,
                verify_keys,
                argv,
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(!check);
                assert!(!verify_keys);
                assert_eq!(argv, vec!["/bin/app", "--flag", "x"]);
            }
            other => panic!("expected Exec, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_check() {
        match parse(&["exec", "--config", "/e.json", "--check"]) {
            Ok(Invocation::Exec {
                config,
                check,
                argv,
                ..
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(check);
                assert!(argv.is_empty());
            }
            other => panic!("expected Exec check, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_verify_keys() {
        match parse(&[
            "exec",
            "--config",
            "/e.json",
            "--verify-keys",
            "--",
            "/bin/app",
        ]) {
            Ok(Invocation::Exec {
                config,
                check,
                verify_keys,
                argv,
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(!check);
                assert!(verify_keys);
                assert_eq!(argv, vec!["/bin/app"]);
            }
            other => panic!("expected Exec with --verify-keys, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_requires_command() {
        assert!(parse(&["exec", "--config", "/e.json"]).is_err());
        assert!(parse(&["exec", "--config", "/e.json", "--"]).is_err());
        assert!(parse(&["exec", "--config", "/e.json", "--check", "--", "/bin/app"]).is_err());
    }

    #[test]
    fn parse_fetch_and_serve_still_work() {
        assert!(matches!(
            parse(&["fetch", "/s.sock"]),
            Ok(Invocation::Fetch(_))
        ));
        assert!(matches!(
            parse(&["--config", "/c.json", "--bind"]),
            Ok(Invocation::Serve(Args { bind: true, .. }))
        ));
    }

    #[test]
    fn parse_help_top_level() {
        assert!(matches!(parse(&["--help"]), Ok(Invocation::Help(None))));
        assert!(matches!(parse(&["-h"]), Ok(Invocation::Help(None))));
    }

    #[test]
    fn parse_help_subcommand() {
        assert!(matches!(parse(&["help"]), Ok(Invocation::Help(None))));
        assert!(matches!(
            parse(&["help", "exec"]),
            Ok(Invocation::Help(Some(s))) if s == "exec"
        ));
        assert!(matches!(
            parse(&["help", "setup"]),
            Ok(Invocation::Help(Some(s))) if s == "setup"
        ));
    }

    #[test]
    fn parse_version() {
        assert!(matches!(parse(&["--version"]), Ok(Invocation::Version)));
        assert!(matches!(parse(&["-V"]), Ok(Invocation::Version)));
    }

    #[test]
    fn parse_no_args_fails() {
        assert!(parse(&[]).is_err());
    }

    #[test]
    fn parse_unknown_subcommand_fails() {
        let err = parse(&["bogus"]).unwrap_err();
        assert!(err.contains("unknown subcommand"), "{err}");
        assert!(err.contains("Try `postmaster help`"), "{err}");
    }

    #[test]
    fn parse_help_in_exec_subcommand() {
        assert!(matches!(
            parse(&["exec", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "exec"
        ));
    }

    #[test]
    fn parse_help_in_setup_subcommand() {
        assert!(matches!(
            parse(&["setup", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "setup"
        ));
    }

    #[test]
    fn parse_setup_flags() {
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--recheck"]),
            Ok(Invocation::Setup { recheck: true, .. })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--unattended"]),
            Ok(Invocation::Setup {
                unattended: true,
                ..
            })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--force"]),
            Ok(Invocation::Setup { force: true, .. })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--keys-dir", "/custom"]),
            Ok(Invocation::Setup { keys_dir: Some(p), .. }) if &*p == std::path::Path::new("/custom")
        ));
    }

    #[test]
    fn parse_cleanup() {
        assert!(matches!(
            parse(&["cleanup", "--config", "/e.json"]),
            Ok(Invocation::Cleanup { config }) if &*config == std::path::Path::new("/e.json")
        ));
        assert!(parse(&["cleanup"]).is_err());
        assert!(parse(&["cleanup", "--config"]).is_err());
    }

    #[test]
    fn parse_help_in_cleanup_subcommand() {
        assert!(matches!(
            parse(&["cleanup", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "cleanup"
        ));
    }
}
